<script setup>
import {ref,onMounted} from 'vue'
import {api} from '../api/library.js'
const rows=ref([]),page=ref(1),total=ref(0),term=ref(''),name=ref(''),pass=ref(''),quota=ref(0),busy=ref(false),msg=ref('')
async function load(n=1){const d=await api(`/admin/users?${new URLSearchParams({q:term.value,page:n,per_page:10})}`);rows.value=d.users;total.value=d.total;page.value=d.page}
async function act(fn){if(busy.value)return;busy.value=true;msg.value='';try{await fn()}catch(e){msg.value=e.message}finally{busy.value=false}}
onMounted(()=>act(load))
async function create(){await api('/admin/users',{username:name.value,password:pass.value,quota:quota.value});pass.value='';name.value='';await load()}
async function modify(u,action){let data={},method='POST';if(action==='quota'){const v=window.prompt('输入要调整的次数（可为负数）');if(v===null||!/^[-+]?\d+$/.test(v.trim()))return;data={delta:Number(v)}}else if(!window.confirm(`确认${{disable:'停用',enable:'启用',delete:'删除'}[action]}「${u.username}」？`))return;if(action==='delete')method='DELETE';await api(`/admin/users/${u.id}${action==='delete'?'':'/'+action}`,method==='DELETE'?undefined:data,method);await load(page.value)}
</script><template><section><h2>用户管理</h2><form class="searchbox" @submit.prevent="act(load)"><input aria-label="按用户名查找" placeholder="按用户名查找" v-model="term"><button :disabled="busy">搜索</button></form><details><summary>创建用户</summary><form class="stack" @submit.prevent="act(create)"><label>用户名<input v-model="name" required></label><label>初始密码<input v-model="pass" type="password" required autocomplete="new-password"></label><label>下载次数<input v-model.number="quota" type="number" min="0" required></label><button :disabled="busy">创建用户</button></form></details><article class="panel" v-for="u in rows" :key="u.id"><h3>{{u.username}}</h3><p>{{u.is_admin?'管理员':u.is_disabled?'已停用':'正常'}}　剩余 {{u.download_quota}} 次</p><div v-if="!u.is_admin" class="row"><button :disabled="busy" @click="act(()=>modify(u,'quota'))">调整次数</button><button :disabled="busy" @click="act(()=>modify(u,u.is_disabled?'enable':'disable'))">{{u.is_disabled?'启用':'停用'}}</button><button :disabled="busy" @click="act(()=>modify(u,'delete'))">删除</button></div></article><div v-if="total>10" class="row"><button :disabled="busy||page===1" @click="act(()=>load(page-1))">上一页</button>{{page}}<button :disabled="busy||page*10>=total" @click="act(()=>load(page+1))">下一页</button></div><p role="status">{{msg}}</p><button disabled>导出数据库</button><small> 当前服务未提供导出接口</small></section></template>
